package java.util;
import java.util.function.*;
public final class Optional<T> {private static final Optional<?> EMPTY=new Optional<Object>(null);private final T value;private Optional(T v){value=v;}public static <T> Optional<T> empty(){return (Optional<T>)EMPTY;}public static <T> Optional<T> of(T v){return new Optional<T>(Objects.requireNonNull(v));}public static <T> Optional<T> ofNullable(T v){return v==null?Optional.<T>empty():of(v);}public T get(){if(value==null)throw new NoSuchElementException("No value present");return value;}public boolean isPresent(){return value!=null;}public void ifPresent(Consumer<? super T> c){if(value!=null)c.accept(value);}public Optional<T> filter(Predicate<? super T> p){Objects.requireNonNull(p);return value==null||p.test(value)?this:Optional.<T>empty();}public <U> Optional<U> map(Function<? super T,? extends U> f){Objects.requireNonNull(f);return value==null?Optional.<U>empty():ofNullable(f.apply(value));}public <U> Optional<U> flatMap(Function<? super T,Optional<U>> f){Objects.requireNonNull(f);return value==null?Optional.<U>empty():Objects.requireNonNull(f.apply(value));}public T orElse(T other){return value==null?other:value;}public T orElseGet(Supplier<? extends T> s){return value==null?s.get():value;}public <X extends Throwable> T orElseThrow(Supplier<? extends X> s) throws X {if(value!=null)return value;throw s.get();}public boolean equals(Object o){return o instanceof Optional&&Objects.equals(value,((Optional<?>)o).value);}public int hashCode(){return Objects.hashCode(value);}public String toString(){return value==null?"Optional.empty":"Optional["+value+"]";}}
